public class ReportController : Controller
{
    // Pattern 1: Response.End() → return a result object.
    // In ASP.NET Core, action methods return IActionResult — no need to
    // manually write to the response stream or call Response.End().
    [HttpPost]
    public IActionResult Export()
    {
        var data = GenerateReport();
        return File(
            System.Text.Encoding.UTF8.GetBytes(data),
            "text/csv",
            "report.csv");
    }

    // Pattern 2: Response.Redirect(url, true) → return RedirectResult.
    // The ThreadAbortException catch block is eliminated entirely because
    // ASP.NET Core redirects never throw — they just set a 302 status.
    [HttpPost]
    public IActionResult ProcessAction()
    {
        if (!User.Identity?.IsAuthenticated ?? true)
        {
            return Redirect("/login");
        }

        try
        {
            ProcessRequest();
            return Redirect("/success");
        }
        catch (Exception ex)
        {
            LogError(ex);
            return Redirect("/error");
        }
    }

